import {mountMotion} from 'klic-design/motions/runtime';
import 'klic-design/motions/runtime.css';
import recipe from 'klic-design/motions/pinch-zoom';
const host=document.querySelector('[data-klic-motion-root]');
if(!host)throw new Error('Add a [data-klic-motion-root] element before mounting.');
const motion=mountMotion(host,recipe);
void motion.ready.catch(error=>{if(host?.isConnected)host.dataset.motionError=error instanceof Error?error.message:String(error);});
export default motion;

